template.css:
.patient-info-card {
  background: #1a1a2e;
  border: 2px solid #00ccff;
  border-radius: 8px;
  overflow: hidden;
}
.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px;
  background: linear-gradient(135deg, #1a1a2e, #16213e);
  border-bottom: 2px solid #00ccff;
}
.patient-icon {
  font-size: 2em;
}
.patient-name {
  font-size: 1.3em;
  font-weight: bold;
  color: #00ff88;
}
.card-body {
  padding: 15px;
}
.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.info-item {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.info-label {
  font-size: 0.75em;
  color: #888;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.info-value {
  font-size: 1em;
  color: #00ccff;
  font-weight: bold;
}

template.js:
function initPatientInfoCard(element, config) {
  function updatePatientInfo(data) {
    if (data.patientName) {
      element.querySelector('#' + config.id + '-name').textContent = data.patientName;
    }
    if (data.patientID) {
      element.querySelector('#' + config.id + '-pid').textContent = data.patientID;
    }
    if (data.age && data.sex) {
      element.querySelector('#' + config.id + '-demographics').textContent = data.age + '/' + data.sex;
    }
    if (data.studyDate) {
      element.querySelector('#' + config.id + '-date').textContent = data.studyDate;
    }
    if (data.modality) {
      element.querySelector('#' + config.id + '-modality').textContent = data.modality;
    }
    if (data.studyDescription) {
      element.querySelector('#' + config.id + '-description').textContent = data.studyDescription;
    }
  }

  return { updatePatientInfo };
}
